arguments.file_text:
@using sv_54f4984897154163aae9dca9220a0196.Services
@inject ISettingsService SettingsService

<div class="section-header">
    <h2>Profile</h2>
    <p>Manage your personal information and public profile.</p>
</div>

@if (_toastMessage is not null)
{
    <div class="toast-message @(_toastIsError ? "toast-error" : "toast-success")">
        @_toastMessage
    </div>
}

@if (_loading)
{
    <div class="loading-spinner">Loading profile…</div>
}
else
{
    <div class="profile-layout">
        <div class="profile-form">
            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="_displayName" @bind:event="oninput" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="_email" @bind:event="oninput" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" @bind="_bio" @bind:event="oninput" rows="4"></textarea>
            </div>

            <div class="form-group">
                <label for="avatarUrl">Avatar URL</label>
                <input id="avatarUrl" type="text" @bind="_avatarUrl" @bind:event="oninput" />
            </div>
        </div>

        <div class="avatar-preview-area">
            <label>Avatar Preview</label>
            <div class="avatar-frame">
                @if (!string.IsNullOrWhiteSpace(_avatarUrl))
                {
                    <img src="@_avatarUrl" alt="Avatar preview" class="avatar-image" />
                }
                else
                {
                    <div class="avatar-placeholder">No avatar</div>
                }
            </div>
            <span class="avatar-url-display" title="@_avatarUrl">@TruncateUrl(_avatarUrl)</span>
        </div>
    </div>

    <div class="button-group">
        <button class="btn btn-primary" @onclick="SaveChanges" disabled="@_saving">
            @(_saving ? "Saving…" : "Save Changes")
        </button>
        <button class="btn btn-secondary" @onclick="DiscardChanges" disabled="@_saving">
            Discard Changes
        </button>
    </div>
}

@code {
    private string _displayName = "";
    private string _email = "";
    private string _bio = "";
    private string _avatarUrl = "";

    private UserProfile? _savedProfile;
    private bool _loading = true;
    private bool _saving;
    private string? _toastMessage;
    private bool _toastIsError;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfile();
    }

    private async Task LoadProfile()
    {
        _loading = true;
        try
        {
            _savedProfile = await SettingsService.GetProfileAsync();
            ApplyProfile(_savedProfile);
        }
        catch
        {
            ShowToast("Failed to load profile.", isError: true);
        }
        finally
        {
            _loading = false;
        }
    }

    private void ApplyProfile(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _bio = profile.Bio;
        _avatarUrl = profile.AvatarUrl;
    }

    private async Task SaveChanges()
    {
        _saving = true;
        _toastMessage = null;
        try
        {
            var updated = new UserProfile(_displayName, _email, _avatarUrl, _bio);
            await SettingsService.SaveProfileAsync(updated);
            _savedProfile = updated;
            ShowToast("Profile saved successfully.");
        }
        catch
        {
            ShowToast("Failed to save profile.", isError: true);
        }
        finally
        {
            _saving = false;
        }
    }

    private void DiscardChanges()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
            _toastMessage = null;
        }
    }

    private void ShowToast(string message, bool isError = false)
    {
        _toastMessage = message;
        _toastIsError = isError;
    }

    private static string TruncateUrl(string? url)
    {
        if (string.IsNullOrWhiteSpace(url)) return "—";
        return url.Length > 50 ? string.Concat(url.AsSpan(0, 47), "...") : url;
    }
}

.profile-layout {
    display: flex;
    gap: 2rem;
    flex-wrap: wrap;
}

.profile-form {
    flex: 1;
    min-width: 300px;
}

.avatar-preview-area {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.75rem;
}

.avatar-preview-area > label {
    font-weight: 500;
    color: #333;
    font-size: 0.9rem;
}

.avatar-frame {
    width: 120px;
    height: 120px;
    border-radius: 50%;
    overflow: hidden;
    border: 3px solid #e5e7eb;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #f9fafb;
}

.avatar-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-placeholder {
    color: #9ca3af;
    font-size: 0.85rem;
}

.avatar-url-display {
    font-size: 0.75rem;
    color: #888;
    max-width: 180px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    text-align: center;
}

@using sv_54f4984897154163aae9dca9220a0196.Services
@inject ISettingsService SettingsService

<div class="section-header">
    <h2>Notifications</h2>
    <p>Choose how and when you want to be notified.</p>
</div>

@if (_toastMessage is not null)
{
    <div class="toast-message @(_toastIsError ? "toast-error" : "toast-success")">
        @_toastMessage
    </div>
}

@if (_loading)
{
    <div class="loading-spinner">Loading notification preferences…</div>
}
else
{
    <div class="toggle-row">
        <div>
            <div class="toggle-label">Email Notifications</div>
            <div class="toggle-description">Receive notifications via email</div>
        </div>
        <label class="toggle-switch">
            <input type="checkbox" @bind="_emailNotifications" />
            <span class="toggle-slider"></span>
        </label>
    </div>

    <div class="toggle-row">
        <div>
            <div class="toggle-label">Push Notifications</div>
            <div class="toggle-description">Receive push notifications in your browser</div>
        </div>
        <label class="toggle-switch">
            <input type="checkbox" @bind="_pushNotifications" />
            <span class="toggle-slider"></span>
        </label>
    </div>

    <div class="toggle-row">
        <div>
            <div class="toggle-label">Weekly Digest</div>
            <div class="toggle-description">Get a summary of activity each week</div>
        </div>
        <label class="toggle-switch">
            <input type="checkbox" @bind="_weeklyDigest" />
            <span class="toggle-slider"></span>
        </label>
    </div>

    <div class="channels-section">
        <h4>Muted Channels</h4>
        <p class="channels-description">Select channels to mute notifications from.</p>
        <div class="channel-list">
            @foreach (var channel in _allChannels)
            {
                <label class="channel-item">
                    <input type="checkbox"
                           checked="@_mutedChannels.Contains(channel)"
                           @onchange="e => ToggleMuteChannel(channel, (bool)e.Value!)" />
                    <span>@channel</span>
                </label>
            }
        </div>
    </div>

    <div class="button-group">
        <button class="btn btn-primary" @onclick="SavePreferences" disabled="@_saving">
            @(_saving ? "Saving…" : "Save Preferences")
        </button>
    </div>
}

@code {
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();
    private bool _loading = true;
    private bool _saving;
    private string? _toastMessage;
    private bool _toastIsError;

    // Available channels for the mute list
    private readonly List<string> _allChannels = new()
    {
        "General", "Announcements", "Engineering", "Design", "Marketing", "Support", "Random"
    };

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        try
        {
            var prefs = await SettingsService.GetNotificationPrefsAsync();
            _emailNotifications = prefs.EmailNotifications;
            _pushNotifications = prefs.PushNotifications;
            _weeklyDigest = prefs.WeeklyDigest;
            _mutedChannels = new HashSet<string>(prefs.MutedChannels);
        }
        catch
        {
            ShowToast("Failed to load notification preferences.", isError: true);
        }
        finally
        {
            _loading = false;
        }
    }

    private void ToggleMuteChannel(string channel, bool isMuted)
    {
        if (isMuted)
