@code {
    private SecuritySettings? _settings;
    private bool _loading = true;
    private string? _toastMessage;
    private bool _toastIsError;

    // Change password
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordError;
    private bool _changingPassword;

    // 2FA
    private bool _twoFactorEnabled;

    // Session revocation
    private string? _confirmRevokeId;
    private bool _revoking;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        try
        {
            _settings = await SettingsService.GetSecuritySettingsAsync();
            _twoFactorEnabled = _settings.TwoFactorEnabled;
        }
        catch
        {
            ShowToast("Failed to load security settings.", isError: true);
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task UpdatePassword()
    {
        _passwordError = null;

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _passwordError = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(_newPassword) || _newPassword.Length < 8)
        {
            _passwordError = "New password must be at least 8 characters.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "New passwords do not match.";
            return;
        }

        _changingPassword = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
            _passwordPanelOpen = false;
            ShowToast("Password updated successfully.");
        }
        catch
        {
            ShowToast("Failed to update password.", isError: true);
        }
        finally
        {
            _changingPassword = false;
        }
    }

    private void RequestRevoke(string sessionId) => _confirmRevokeId = sessionId;
    private void CancelRevoke() => _confirmRevokeId = null;

    private async Task ConfirmRevoke(string sessionId)
    {
        _revoking = true;
        try
        {
            await SettingsService.RevokeSessionAsync(sessionId);
            if (_settings is not null)
            {
                var updated = _settings.Sessions.Where(s => s.Id != sessionId).ToList();
                _settings = _settings with { Sessions = updated };
            }
            _confirmRevokeId = null;
            ShowToast("Session revoked.");
        }
        catch
        {
            ShowToast("Failed to revoke session.", isError: true);
        }
        finally
        {
            _revoking = false;
        }
    }

    private void ShowToast(string message, bool isError = false)
    {
        _toastMessage = message;
        _toastIsError = isError;
    }
}

