    </div>
}

@if (_loading)
{
    <div class="loading-spinner">Loading appearance settings…</div>
}
else
{
    <div class="appearance-layout">
        <div class="appearance-form">
            <!-- Theme Selector -->
            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    @foreach (var theme in _themes)
                    {
                        <label class="radio-option">
                            <input type="radio" name="theme" value="@theme.Value"
                                   checked="@(_theme == theme.Value)"
                                   @onchange="() => _theme = theme.Value" />
                            <span class="radio-label">@theme.Icon @theme.Label</span>
                        </label>
                    }
                </div>
            </div>

            <!-- Font Size Selector -->
            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    @foreach (var size in _fontSizes)
                    {
                        <label class="radio-option">
                            <input type="radio" name="fontSize" value="@size.Value"
                                   checked="@(_fontSize == size.Value)"
                                   @onchange="() => _fontSize = size.Value" />
                            <span class="radio-label">@size.Label</span>
                        </label>
                    }
                </div>
            </div>

            <!-- Language Dropdown -->
            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="_language">
                    @foreach (var lang in _languages)
                    {
                        <option value="@lang.Value">@lang.Label</option>
                    }
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="toggle-row">
                <div>
                    <div class="toggle-label">Compact Mode</div>
                    <div class="toggle-description">Reduce spacing and padding throughout the UI</div>
                </div>
                <label class="toggle-switch">
                    <input type="checkbox" @bind="_compactMode" />
                    <span class="toggle-slider"></span>
                </label>
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@_saving">
                    @(_saving ? "Saving…" : "Save")
                </button>
            </div>
        </div>

        <!-- Live Preview -->
        <div class="preview-area">
            <label>Live Preview</label>
            <div class="preview-card @GetPreviewThemeClass()" style="@GetPreviewFontStyle()">
                <div class="preview-header">
                    <div class="preview-title">Preview</div>
                    <div class="preview-subtitle">This is how your settings will look</div>
                </div>
                <div class="preview-body @(_compactMode ? "compact" : "")">
                    <div class="preview-nav">
                        <div class="preview-nav-item active">Dashboard</div>
                        <div class="preview-nav-item">Messages</div>
                        <div class="preview-nav-item">Settings</div>
                    </div>
                    <div class="preview-content">
                        <p class="preview-text">
                            Theme: <strong>@_theme</strong> ·
                            Font: <strong>@_fontSize</strong> ·
                            Language: <strong>@_language</strong>
                        </p>
                        <p class="preview-text">
                            Compact mode is <strong>@(_compactMode ? "on" : "off")</strong>.
                        </p>
                        <div class="preview-button">Sample Button</div>
                    </div>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;

    private bool _loading = true;
    private bool _saving;
    private string? _toastMessage;
    private bool _toastIsError;

    private readonly List<ThemeOption> _themes = new()
    {
        new("Light", "Light", "☀️"),
        new("Dark", "Dark", "🌙"),
        new("System", "System", "💻")
    };

    private readonly List<SizeOption> _fontSizes = new()
    {
        new("Small", "Small"),
        new("Medium", "Medium"),
        new("Large", "Large")
    };

    private readonly List<LanguageOption> _languages = new()
    {
        new("en", "English"),
        new("es", "Español"),
        new("fr", "Français"),
        new("de", "Deutsch"),
        new("ja", "日本語"),
        new("zh", "中文")
    };

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        try
        {
            var settings = await SettingsService.GetAppearanceAsync();
            _theme = settings.Theme;
            _fontSize = settings.FontSize;
            _language = settings.Language;
            _compactMode = settings.CompactMode;
        }
        catch
        {
            ShowToast("Failed to load appearance settings.", isError: true);
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task SaveAppearance()
    {
        _saving = true;
        _toastMessage = null;
        try
        {
            var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
            await SettingsService.SaveAppearanceAsync(settings);
            ShowToast("Appearance settings saved.");
        }
        catch
        {
            ShowToast("Failed to save appearance settings.", isError: true);
        }
        finally
        {
            _saving = false;
        }
    }

    private string GetPreviewThemeClass() => _theme switch
    {
        "Dark" => "preview-dark",
        "Light" => "preview-light",
        _ => "preview-system"
    };

    private string GetPreviewFontStyle() => _fontSize switch
    {
        "Small" => "font-size: 0.8rem;",
        "Large" => "font-size: 1.1rem;",
        _ => "font-size: 0.95rem;"
    };

    private void ShowToast(string message, bool isError = false)
    {
        _toastMessage = message;
        _toastIsError = isError;
    }

    private record ThemeOption(string Value, string Label, string Icon);
    private record SizeOption(string Value, string Label);
    private record LanguageOption(string Value, string Label);
}
