    display: flex;
    gap: 2.5rem;
    flex-wrap: wrap;
}

.appearance-form {
    flex: 1;
    min-width: 300px;
}

.radio-group {
    display: flex;
    gap: 0.5rem;
    flex-wrap: wrap;
}

.radio-option {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.5rem 1rem;
    border: 1px solid #d1d5db;
    border-radius: 6px;
    cursor: pointer;
    transition: all 0.15s;
    font-weight: 400;
}

.radio-option:hover {
    border-color: #2563eb;
    background: #f0f4ff;
}

.radio-option input[type="radio"] {
    accent-color: #2563eb;
}

.radio-label {
    font-size: 0.9rem;
}

/* Preview Area */
.preview-area {
    min-width: 280px;
    max-width: 360px;
}

.preview-area > label {
    display: block;
    font-weight: 500;
    color: #333;
    font-size: 0.9rem;
    margin-bottom: 0.5rem;
}

.preview-card {
    border-radius: 8px;
    overflow: hidden;
    border: 1px solid #e5e7eb;
    transition: all 0.3s;
}

.preview-light {
    background: #ffffff;
    color: #1a1a2e;
}

.preview-dark {
    background: #1e1e2e;
    color: #e0e0e0;
    border-color: #333;
}

.preview-system {
    background: linear-gradient(135deg, #ffffff 50%, #1e1e2e 50%);
    color: #1a1a2e;
    border-color: #bbb;
}

.preview-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid rgba(128, 128, 128, 0.2);
}

.preview-title {
    font-weight: 600;
    font-size: 1em;
}

.preview-subtitle {
    font-size: 0.8em;
    opacity: 0.7;
}

.preview-body {
    padding: 0.75rem 1rem;
}

.preview-body.compact {
    padding: 0.4rem 0.75rem;
}

.preview-nav {
    display: flex;
    gap: 0.5rem;
    margin-bottom: 0.75rem;
}

.preview-body.compact .preview-nav {
    margin-bottom: 0.375rem;
    gap: 0.25rem;
}

.preview-nav-item {
    padding: 0.25rem 0.625rem;
    border-radius: 4px;
    font-size: 0.8em;
    opacity: 0.6;
}

.preview-nav-item.active {
    opacity: 1;
    font-weight: 600;
}

.preview-light .preview-nav-item.active,
.preview-system .preview-nav-item.active {
    background: #eff6ff;
    color: #2563eb;
}

.preview-dark .preview-nav-item.active {
    background: #2563eb33;
    color: #93b4f5;
}

.preview-text {
    font-size: 0.85em;
    margin: 0.375rem 0;
    opacity: 0.85;
}

.preview-body.compact .preview-text {
    margin: 0.2rem 0;
}

.preview-button {
    display: inline-block;
    margin-top: 0.5rem;
    padding: 0.3rem 0.875rem;
    border-radius: 4px;
    font-size: 0.8em;
    font-weight: 500;
}

.preview-light .preview-button,
.preview-system .preview-button {
    background: #2563eb;
    color: #fff;
}

.preview-dark .preview-button {
    background: #3b82f6;
    color: #fff;
}
