.channels-section {
    margin-top: 1.5rem;
}

.channels-section h4 {
    margin: 0 0 0.25rem;
    font-size: 1rem;
    font-weight: 600;
    color: #1a1a2e;
}

.channels-description {
    color: #666;
    font-size: 0.85rem;
    margin: 0 0 0.75rem;
}

.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    max-width: 500px;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem 0.75rem;
    background: #f9fafb;
    border: 1px solid #e5e7eb;
    border-radius: 6px;
    cursor: pointer;
    transition: background 0.15s;
    font-weight: 400;
    font-size: 0.9rem;
}

.channel-item:hover {
    background: #f0f4ff;
}

.channel-item input[type="checkbox"] {
    accent-color: #2563eb;
    width: 16px;
    height: 16px;
}

