@using sv_54f4984897154163aae9dca9220a0196.Services
@inject ISettingsService SettingsService

<div class="section-header">
    <h2>Security</h2>
    <p>Manage your password, two-factor authentication, and active sessions.</p>
</div>

@if (_toastMessage is not null)
{
    <div class="toast-message @(_toastIsError ? "toast-error" : "toast-success")">
        @_toastMessage
    </div>
}

@if (_loading)
{
    <div class="loading-spinner">Loading security settings…</div>
}
else
{
    <!-- Change Password Panel -->
    <div class="expandable-panel">
        <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
            <span>🔑 Change Password</span>
            <span class="panel-chevron @(_passwordPanelOpen ? "open" : "")">▸</span>
        </button>
        @if (_passwordPanelOpen)
        {
            <div class="panel-body">
                <div class="form-group">
                    <label for="currentPassword">Current Password</label>
                    <input id="currentPassword" type="password" @bind="_currentPassword" />
                </div>
                <div class="form-group">
                    <label for="newPassword">New Password</label>
                    <input id="newPassword" type="password" @bind="_newPassword" />
                </div>
                <div class="form-group">
                    <label for="confirmPassword">Confirm New Password</label>
                    <input id="confirmPassword" type="password" @bind="_confirmPassword" />
                </div>
                @if (_passwordError is not null)
                {
                    <div class="field-error">@_passwordError</div>
                }
                <button class="btn btn-primary" @onclick="UpdatePassword" disabled="@_changingPassword">
                    @(_changingPassword ? "Updating…" : "Update Password")
                </button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="twofa-section">
        <div class="toggle-row">
            <div>
                <div class="toggle-label">Two-Factor Authentication</div>
                <div class="toggle-description">
                    @if (_twoFactorEnabled)
                    {
                        <span class="status-badge enabled">Enabled</span>
                    }
                    else
                    {
                        <span class="status-badge disabled">Disabled</span>
                    }
                </div>
            </div>
            <label class="toggle-switch">
                <input type="checkbox" @bind="_twoFactorEnabled" />
                <span class="toggle-slider"></span>
            </label>
        </div>
        @if (_settings?.LastPasswordChange is not null)
        {
            <p class="last-password-change">
                Last password change: @_settings.LastPasswordChange.Value.ToString("MMMM d, yyyy 'at' h:mm tt")
            </p>
        }
    </div>

    <!-- Active Sessions -->
    <div class="sessions-section">
        <h4>Active Sessions</h4>
        @if (_settings?.Sessions is { Count: > 0 })
        {
            <div class="sessions-table-wrapper">
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in _settings.Sessions)
                        {
                            <tr>
                                <td>@session.Device</td>
                                <td>@session.Location</td>
                                <td>@session.LastActive.ToString("MMM d, yyyy h:mm tt")</td>
                                <td>
                                    @if (session != _settings.Sessions[0])
                                    {
                                        @if (_confirmRevokeId == session.Id)
                                        {
                                            <div class="revoke-confirm">
                                                <span>Revoke this session?</span>
                                                <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevoke(session.Id)" disabled="@_revoking">
                                                    Yes
                                                </button>
                                                <button class="btn btn-secondary btn-sm" @onclick="CancelRevoke">
                                                    No
                                                </button>
                                            </div>
                                        }
                                        else
                                        {
                                            <button class="btn btn-danger btn-sm" @onclick="() => RequestRevoke(session.Id)">
                                                Revoke
                                            </button>
                                        }
                                    }
                                    else
                                    {
                                        <span class="current-session-badge">Current</span>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>
        }
        else
        {
            <p class="no-sessions">No active sessions found.</p>
        }
    </div>
}

@code {
    private SecuritySettings? _settings;
    private bool _loading = true;
    private string? _toastMessage;
    private bool _toastIsError;

    // Change password
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordError;
    private bool _changingPassword;

    // 2FA
    private bool _twoFactorEnabled;

    // Session revocation
    private string? _confirmRevokeId;
    private bool _revoking;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        try
        {
            _settings = await SettingsService.GetSecuritySettingsAsync();
            _twoFactorEnabled = _settings.TwoFactorEnabled;
        }
        catch
        {
            ShowToast("Failed to load security settings.", isError: true);
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task UpdatePassword()
    {
        _passwordError = null;

        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            _passwordError = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(_newPassword) || _newPassword.Length < 8)
        {
            _passwordError = "New password must be at least 8 characters.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "New passwords do not match.";
            return;
        }

        _changingPassword = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
            _passwordPanelOpen = false;
            ShowToast("Password updated successfully.");
        }
        catch
        {
            ShowToast("Failed to update password.", isError: true);
        }
        finally
        {
            _changingPassword = false;
        }
    }

    private void RequestRevoke(string sessionId) => _confirmRevokeId = sessionId;
    private void CancelRevoke() => _confirmRevokeId = null;

    private async Task ConfirmRevoke(string sessionId)
    {
        _revoking = true;
        try
        {
            await SettingsService.RevokeSessionAsync(sessionId);
            if (_settings is not null)
            {
                var updated = _settings.Sessions.Where(s => s.Id != sessionId).ToList();
                _settings = _settings with { Sessions = updated };
            }
            _confirmRevokeId = null;
            ShowToast("Session revoked.");
        }
        catch
        {
            ShowToast("Failed to revoke session.", isError: true);
        }
        finally
        {
            _revoking = false;
        }
    }

    private void ShowToast(string message, bool isError = false)
    {
        _toastMessage = message;
        _toastIsError = isError;
    }
}

