.expandable-panel {
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    overflow: hidden;
    margin-bottom: 1.5rem;
    max-width: 500px;
}

.panel-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    padding: 0.875rem 1rem;
    background: #f9fafb;
    border: none;
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 600;
    color: #1a1a2e;
    transition: background 0.15s;
}

.panel-header:hover {
    background: #f0f4ff;
}

.panel-chevron {
    transition: transform 0.2s;
    font-size: 0.85rem;
}

.panel-chevron.open {
    transform: rotate(90deg);
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid #e5e7eb;
}

.field-error {
    color: #dc2626;
    font-size: 0.85rem;
    margin-bottom: 0.75rem;
}

.twofa-section {
    margin-bottom: 1.5rem;
}

.status-badge {
    display: inline-block;
    padding: 0.125rem 0.5rem;
    border-radius: 12px;
    font-size: 0.75rem;
    font-weight: 600;
}

.status-badge.enabled {
    background: #dcfce7;
    color: #166534;
}

.status-badge.disabled {
    background: #fee2e2;
    color: #991b1b;
}

.last-password-change {
    font-size: 0.85rem;
    color: #888;
    margin-top: 0.5rem;
}

.sessions-section {
    margin-top: 1rem;
}

.sessions-section h4 {
    margin: 0 0 0.75rem;
    font-size: 1rem;
    font-weight: 600;
    color: #1a1a2e;
}

.sessions-table-wrapper {
    overflow-x: auto;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
}

.sessions-table th {
    text-align: left;
    padding: 0.625rem 0.75rem;
    background: #f9fafb;
    border-bottom: 2px solid #e5e7eb;
    font-weight: 600;
