+                            <span class="radio-label">@size.Label</span>
+                        </label>
+                    }
+                </div>
+            </div>
+
+            <!-- Language Dropdown -->
+            <div class="form-group">
+                <label for="language">Language</label>
+                <select id="language" @bind="_language">
+                    @foreach (var lang in _languages)
+                    {
+                        <option value="@lang.Value">@lang.Label</option>
+                    }
+                </select>
+            </div>
+
+            <!-- Compact Mode -->
+            <div class="toggle-row">
+                <div>
+                    <div class="toggle-label">Compact Mode</div>
+                    <div class="toggle-description">Reduce spacing and padding throughout the UI</div>
+                </div>
+                <label class="toggle-switch">
+                    <input type="checkbox" @bind="_compactMode" />
+                    <span class="toggle-slider"></span>
+                </label>
+            </div>
+
+            <div class="button-group">
+                <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@_saving">
+                    @(_saving ? "Saving…" : "Save")
+                </button>
+            </div>
+        </div>
+
+        <!-- Live Preview -->
+        <div class="preview-area">
+            <label>Live Preview</label>
+            <div class="preview-card @GetPreviewThemeClass()" style="@GetPreviewFontStyle()">
+                <div class="preview-header">
+                    <div class="preview-title">Preview</div>
+                    <div class="preview-subtitle">This is how your settings will look</div>
+                </div>
+                <div class="preview-body @(_compactMode ? "compact" : "")">
+                    <div class="preview-nav">
+                        <div class="preview-nav-item active">Dashboard</div>
+                        <div class="preview-nav-item">Messages</div>
+                        <div class="preview-nav-item">Settings</div>
+                    </div>
+                    <div class="preview-content">
+                        <p class="preview-text">
+                            Theme: <strong>@_theme</strong> ·
+                            Font: <strong>@_fontSize</strong> ·
+                            Language: <strong>@_language</strong>
+                        </p>
+                        <p class="preview-text">
+                            Compact mode is <strong>@(_compactMode ? "on" : "off")</strong>.
+                        </p>
+                        <div class="preview-button">Sample Button</div>
+                    </div>
+                </div>
+            </div>
+        </div>
+    </div>
+}
+
+@code {
+    private string _theme = "System";
+    private string _fontSize = "Medium";
+    private string _language = "en";
+    private bool _compactMode;
+
+    private bool _loading = true;
+    private bool _saving;
+    private string? _toastMessage;
+    private bool _toastIsError;
+
+    private readonly List<ThemeOption> _themes = new()
+    {
+        new("Light", "Light", "☀️"),
+        new("Dark", "Dark", "🌙"),
+        new("System", "System", "💻")
+    };
+
+    private readonly List<SizeOption> _fontSizes = new()
+    {
+        new("Small", "Small"),
+        new("Medium", "Medium"),
+        new("Large", "Large")
+    };
+
+    private readonly List<LanguageOption> _languages = new()
+    {
+        new("en", "English"),
+        new("es", "Español"),
+        new("fr", "Français"),
+        new("de", "Deutsch"),
+        new("ja", "日本語"),
+        new("zh", "中文")
+    };
+
+    protected override async Task OnInitializedAsync()
+    {
+        _loading = true;
+        try
+        {
+            var settings = await SettingsService.GetAppearanceAsync();
+            _theme = settings.Theme;
+            _fontSize = settings.FontSize;
+            _language = settings.Language;
+            _compactMode = settings.CompactMode;
+        }
+        catch
+        {
+            ShowToast("Failed to load appearance settings.", isError: true);
+        }
+        finally
+        {
+            _loading = false;
+        }
+    }
+
+    private async Task SaveAppearance()
+    {
+        _saving = true;
+        _toastMessage = null;
+        try
+        {
+            var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
+            await SettingsService.SaveAppearanceAsync(settings);
+            ShowToast("Appearance settings saved.");
+        }
+        catch
+        {
+            ShowToast("Failed to save appearance settings.", isError: true);
+        }
+        finally
+        {
+            _saving = false;
+        }
+    }
+
+    private string GetPreviewThemeClass() => _theme switch
+    {
+        "Dark" => "preview-dark",
+        "Light" => "preview-light",
+        _ => "preview-system"
+    };
+
+    private string GetPreviewFontStyle() => _fontSize switch
+    {
+        "Small" => "font-size: 0.8rem;",
+        "Large" => "font-size: 1.1rem;",
+        _ => "font-size: 0.95rem;"
+    };
+
+    private void ShowToast(string message, bool isError = false)
+    {
+        _toastMessage = message;
+        _toastIsError = isError;
+    }
+
+    private record ThemeOption(string Value, string Label, string Icon);
+    private record SizeOption(string Value, string Label);
+    private record LanguageOption(string Value, string Label);
+}
+

toolArgs.file_text:
.appearance-layout {
    display: flex;
    gap: 2.5rem;
    flex-wrap: wrap;
}

.appearance-form {
    flex: 1;
    min-width: 300px;
}

.radio-group {
    display: flex;
    gap: 0.5rem;
    flex-wrap: wrap;
}

.radio-option {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.5rem 1rem;
    border: 1px solid #d1d5db;
    border-radius: 6px;
    cursor: pointer;
    transition: all 0.15s;
    font-weight: 400;
}

.radio-option:hover {
    border-color: #2563eb;
    background: #f0f4ff;
}

.radio-option input[type="radio"] {
    accent-color: #2563eb;
}

.radio-label {
    font-size: 0.9rem;
}

/* Preview Area */
.preview-area {
    min-width: 280px;
    max-width: 360px;
}

.preview-area > label {
    display: block;
    font-weight: 500;
    color: #333;
    font-size: 0.9rem;
    margin-bottom: 0.5rem;
}

.preview-card {
    border-radius: 8px;
    overflow: hidden;
    border: 1px solid #e5e7eb;
    transition: all 0.3s;
}

.preview-light {
    background: #ffffff;
    color: #1a1a2e;
}

.preview-dark {
    background: #1e1e2e;
    color: #e0e0e0;
    border-color: #333;
}

.preview-system {
    background: linear-gradient(135deg, #ffffff 50%, #1e1e2e 50%);
    color: #1a1a2e;
    border-color: #bbb;
}

.preview-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid rgba(128, 128, 128, 0.2);
}

.preview-title {
    font-weight: 600;
    font-size: 1em;
}

.preview-subtitle {
    font-size: 0.8em;
    opacity: 0.7;
}

.preview-body {
    padding: 0.75rem 1rem;
}

.preview-body.compact {
    padding: 0.4rem 0.75rem;
}

.preview-nav {
    display: flex;
    gap: 0.5rem;
    margin-bottom: 0.75rem;
}

.preview-body.compact .preview-nav {
    margin-bottom: 0.375rem;
    gap: 0.25rem;
}

.preview-nav-item {
    padding: 0.25rem 0.625rem;
    border-radius: 4px;
    font-size: 0.8em;
    opacity: 0.6;
}

.preview-nav-item.active {
    opacity: 1;
    font-weight: 600;
}

.preview-light .preview-nav-item.active,
.preview-system .preview-nav-item.active {
    background: #eff6ff;
    color: #2563eb;
}

.preview-dark .preview-nav-item.active {
    background: #2563eb33;
    color: #93b4f5;
}

.preview-text {
    font-size: 0.85em;
    margin: 0.375rem 0;
    opacity: 0.85;
}

.preview-body.compact .preview-text {
    margin: 0.2rem 0;
}

.preview-button {
    display: inline-block;
    margin-top: 0.5rem;
    padding: 0.3rem 0.875rem;
    border-radius: 4px;
    font-size: 0.8em;
    font-weight: 500;
}

.preview-light .preview-button,
.preview-system .preview-button {
    background: #2563eb;
    color: #fff;
}

.preview-dark .preview-button {
    background: #3b82f6;
    color: #fff;
}

